<script setup>
import { t } from '../i18n.js'
import AppIcon from './AppIcon.vue'
import { ripple } from './ripple.js'
import { capturePress } from './activation.js'
import { tooltipDirective as vTooltip } from './tooltip.js'

defineProps({
  label: { type: String, default: '' },
  translateLabel: { type: Boolean, default: true },
  tooltip: String,
  icon: String,
  iconOnly: Boolean,
  highlighted: Boolean,
  destructive: Boolean,
  tonal: Boolean,
  badgeCount: { type: Number, default: 0 },
  showZeroBadge: Boolean,
  type: { type: String, default: 'button' },
  href: String,
})
</script>

<template>
  <component :is="href ? 'a' : 'button'" class="app-button" :href="href" :type="href ? undefined : type" :class="{ 'icon-button': iconOnly, primary: highlighted, danger: destructive, tonal }"
    v-tooltip="tooltip ? t(tooltip) : iconOnly && label ? translateLabel ? t(label) : label : ''" :aria-label="label ? translateLabel ? t(label) : label : undefined" @pointerdown="capturePress($event); ripple($event)">
    <AppIcon v-if="icon" :name="icon" />
    <slot><span v-if="!iconOnly">{{ translateLabel ? t(label) : label }}</span></slot>
    <span v-if="badgeCount > 0 || showZeroBadge" class="app-button-badge" aria-hidden="true">{{ badgeCount > 99 ? '99+' : badgeCount }}</span>
  </component>
</template>
<style>
.app-button:where(:not(.icon-button)) { padding-inline:16px; gap:7px; }
.app-button:where(:not(.icon-button)):where(:has(> .app-icon)) { padding-inline-start:12px; }
.app-button.primary, .app-button.primary:hover:not(:disabled) { color: var(--on-selected); }
a.app-button.icon-button { padding:0; border:0; border-radius:50%; background:transparent; }
a.app-button.icon-button:hover, a.app-button.icon-button:focus-visible { background:color-mix(in srgb, currentColor 8%, transparent); }
.app-button.tonal { background:var(--hover); border-color:var(--outline-variant); border-radius:var(--button-radius); }
.app-button:has(> .app-button-badge) { overflow:visible; }
.icon-button:has(> .app-button-badge, > .action-count) { overflow:visible; }
.icon-button > :is(.app-button-badge, .action-count) { top:-4px; right:-4px; }
.app-button-badge { position:absolute; top:-1px; right:-1px; box-sizing:border-box; min-width:16px; height:16px; padding:0 2px; border:2px solid var(--surface); border-radius:8px; background:var(--error); color:var(--on-selected); font-size:var(--text-caption); font-weight:700; line-height:12px; text-align:center; pointer-events:none; z-index:2; }
</style>
